
const WORDS=[{"id": 0, "w": "月饼", "p": "yuèbǐng", "t": "名词", "m": "bánh Trung thu", "coll": "吃月饼、一盒月饼", "s": "中秋节到了，她特意买了一盒月饼，准备寄给远方的父母。"}, {"id": 1, "w": "清晨", "p": "qīngchén", "t": "名词", "m": "sáng sớm", "coll": "清晨的阳光、清晨出发", "s": "清晨，街上还没有多少行人，他就已经出门工作了。"}, {"id": 2, "w": "迎面", "p": "yíngmiàn", "t": "副词", "m": "trước mặt, đối diện", "coll": "迎面走来、迎面吹来", "s": "一位老人迎面走来，手里提着一个旧布包。"}, {"id": 3, "w": "模样", "p": "múyàng", "t": "名词", "m": "vẻ bề ngoài, diện mạo", "coll": "年轻时的模样、改变模样", "s": "多年没见，我几乎认不出他现在的模样了。"}, {"id": 4, "w": "打量", "p": "dǎliang", "t": "动词", "m": "quan sát (quần áo, diện mạo)", "coll": "仔细打量、上下打量", "s": "她仔细打量着眼前这位陌生人，努力回忆在哪里见过他。"}, {"id": 5, "w": "番", "p": "fān", "t": "量词", "m": "lượt, hồi, lần", "coll": "一番话、一番考虑", "s": "经过一番认真考虑，他终于作出了决定。"}, {"id": 6, "w": "搓", "p": "cuō", "t": "动词", "m": "xoa, vò", "coll": "搓手、搓衣服", "s": "天气太冷，他不停地搓着双手，想让自己暖和一点。"}, {"id": 7, "w": "迟疑", "p": "chíyí", "t": "形容词", "m": "chần chừ, ngập ngừng", "coll": "迟疑片刻、毫不迟疑", "s": "听到这个请求，他迟疑了片刻，还是点头答应了。"}, {"id": 8, "w": "拜托", "p": "bàituō", "t": "动词", "m": "xin nhờ", "coll": "拜托朋友、拜托你一件事", "s": "我想拜托你一件事：帮我把这封信交给老师。"}, {"id": 9, "w": "饱经沧桑", "p": "bǎojīng cāngsāng", "t": "成语", "m": "nếm đủ mùi đời, từng trải", "coll": "饱经沧桑的面容、饱经沧桑的老人", "s": "那位饱经沧桑的老人坐在门口，安静地望着远处的山。"}, {"id": 10, "w": "流露", "p": "liúlù", "t": "动词", "m": "bộc lộ, để lộ ra", "coll": "流露感情、流露出喜悦", "s": "听说儿子要回家，她的眼神中流露出难以掩饰的喜悦。"}, {"id": 11, "w": "朴实", "p": "pǔshí", "t": "形容词", "m": "thật thà, chất phác", "coll": "为人朴实、语言朴实", "s": "他为人朴实，从不刻意炫耀自己的成绩。"}, {"id": 12, "w": "过于", "p": "guòyú", "t": "副词", "m": "quá", "coll": "过于担心、过于简单", "s": "面对孩子的选择，父母不必过于担心。"}, {"id": 13, "w": "操劳", "p": "cāoláo", "t": "动词", "m": "làm việc vất vả", "coll": "为家庭操劳、日夜操劳", "s": "母亲为这个家庭操劳了大半辈子，却很少抱怨。"}, {"id": 14, "w": "胡须", "p": "húxū", "t": "名词", "m": "râu", "coll": "留胡须、花白的胡须", "s": "老人摸了摸自己花白的胡须，缓缓地笑了。"}, {"id": 15, "w": "起码", "p": "qǐmǎ", "t": "副词／形容词", "m": "ít nhất, tối thiểu", "coll": "起码三天、最起码的要求", "s": "这项工作起码需要三天时间，不能急于完成。"}, {"id": 16, "w": "口音", "p": "kǒuyīn", "t": "名词", "m": "giọng", "coll": "家乡口音、带着口音", "s": "虽然离开家乡多年，他说话时仍带着浓重的口音。"}, {"id": 17, "w": "乡镇", "p": "xiāngzhèn", "t": "名词", "m": "thị trấn nhỏ", "coll": "附近的乡镇、乡镇企业", "s": "这条公路连接着附近的几个乡镇，方便了居民出行。"}, {"id": 18, "w": "原先", "p": "yuánxiān", "t": "名词", "m": "ban đầu, trước kia", "coll": "原先的计划、原先住在这里", "s": "我们原先打算周末出发，后来因为天气原因改了计划。"}, {"id": 19, "w": "裁缝", "p": "cáifeng", "t": "名词", "m": "thợ may", "coll": "一位裁缝、找裁缝改衣服", "s": "母亲把旧衣服交给裁缝，请他改得合身一些。"}, {"id": 20, "w": "港口", "p": "gǎngkǒu", "t": "名词", "m": "bến cảng", "coll": "抵达港口、繁忙的港口", "s": "清晨，几艘货船缓缓驶入繁忙的港口。"}, {"id": 21, "w": "斯文", "p": "sīwen", "t": "形容词", "m": "lịch sự, nhã nhặn", "coll": "举止斯文、斯文有礼", "s": "他说话轻声细语，举止斯文，给人留下了很好的印象。"}, {"id": 22, "w": "心眼儿", "p": "xīnyǎnr", "t": "名词", "m": "bụng dạ, lòng", "coll": "心眼儿好、从心眼儿里高兴", "s": "她心眼儿好，谁家遇到困难，她都愿意伸手帮一把。"}, {"id": 23, "w": "信誉", "p": "xìnyù", "t": "名词", "m": "uy tín, danh dự", "coll": "讲信誉、维护信誉", "s": "一家企业只有始终讲信誉，才能赢得顾客的信任。"}, {"id": 24, "w": "欺骗", "p": "qīpiàn", "t": "动词", "m": "lừa gạt", "coll": "欺骗别人、受到欺骗", "s": "他无法接受自己最信任的人竟然欺骗了自己。"}, {"id": 25, "w": "学位", "p": "xuéwèi", "t": "名词", "m": "học vị", "coll": "获得学位、硕士学位", "s": "经过多年的努力，她终于获得了硕士学位。"}, {"id": 26, "w": "一流", "p": "yīliú", "t": "形容词", "m": "hạng nhất", "coll": "一流的服务、一流水平", "s": "这家医院不仅拥有先进的设备，还提供一流的服务。"}, {"id": 27, "w": "主管", "p": "zhǔguản", "t": "名词", "m": "người quản lý", "coll": "部门主管、主管人员", "s": "部门主管认真听取了大家的意见，决定调整工作安排。"}, {"id": 28, "w": "助手", "p": "zhùshǒu", "t": "名词", "m": "trợ lý", "coll": "担任助手、得力助手", "s": "他担任教授的助手，协助整理实验中收集的数据。"}, {"id": 29, "w": "骨干", "p": "gǔgàn", "t": "名词", "m": "trụ cột, rường cột", "coll": "业务骨干、培养骨干", "s": "凭着扎实的专业能力，她很快成为团队里的业务骨干。"}, {"id": 30, "w": "小心翼翼", "p": "xiǎoxīn yìyì", "t": "成语", "m": "thận trọng, dè dặt", "coll": "小心翼翼地打开、小心翼翼地捧着", "s": "他小心翼翼地打开盒子，生怕碰坏里面的礼物。"}, {"id": 31, "w": "喜悦", "p": "xǐyuè", "t": "形容词", "m": "vui sướng", "coll": "充满喜悦、分享喜悦", "s": "她与家人分享成功的喜悦，感谢他们一直以来的支持。"}, {"id": 32, "w": "拨", "p": "bō", "t": "动词", "m": "gọi (điện thoại)", "coll": "拨电话号码、拨通电话", "s": "他拨了几次那个号码，始终没有人接听。"}, {"id": 33, "w": "仍旧", "p": "réngjiù", "t": "副词", "m": "vẫn", "coll": "仍旧保留、仍旧坚持", "s": "多年以后，这条老街仍旧保留着原来的模样。"}, {"id": 34, "w": "隐约", "p": "yǐnyuē", "t": "形容词", "m": "lờ mờ, mang máng, mập mờ", "coll": "隐约看见、隐约听见", "s": "透过清晨的薄雾，我们隐约看见远处的村庄。"}, {"id": 35, "w": "浑身", "p": "húnshēn", "t": "名词", "m": "toàn thân, khắp người", "coll": "浑身是汗、浑身发抖", "s": "跑完步后，他浑身是汗，却觉得格外轻松。"}, {"id": 36, "w": "馅儿", "p": "xiànr", "t": "名词", "m": "nhân (bánh)", "coll": "豆沙馅儿、月饼馅儿", "s": "这种月饼皮薄馅儿多，是奶奶最喜欢的口味。"}, {"id": 37, "w": "灿烂", "p": "cànlàn", "t": "形容词", "m": "rực rỡ, rạng rỡ", "coll": "灿烂的笑容、灿烂的阳光", "s": "看到孩子平安归来，母亲的脸上露出了灿烂的笑容。"}, {"id": 38, "w": "惦记", "p": "diànjì", "t": "动词", "m": "nhớ đến, lo lắng", "coll": "惦记家人、一直惦记", "s": "虽然工作很忙，她还是一直惦记着独自在家的母亲。"}, {"id": 39, "w": "丢人", "p": "diū rén", "t": "动词", "m": "mất mặt, mất thể diện", "coll": "觉得丢人、当众丢人", "s": "做错了事就应该承认，不必觉得丢人。"}, {"id": 40, "w": "炫耀", "p": "xuànyào", "t": "动词", "m": "khoe khoang", "coll": "炫耀财富、炫耀成绩", "s": "真正有本事的人往往不需要到处炫耀自己。"}, {"id": 41, "w": "面子", "p": "miànzi", "t": "名词", "m": "thể diện, sĩ diện", "coll": "顾面子、给面子", "s": "他为了顾面子，始终不肯承认自己的错误。"}, {"id": 42, "w": "辜负", "p": "gūfù", "t": "动词", "m": "phụ lòng", "coll": "辜负期望、辜负信任", "s": "我们应该认真履行承诺，不要辜负别人的信任。"}, {"id": 43, "w": "期望", "p": "qīwàng", "t": "动词／名词", "m": "kỳ vọng, mong đợi", "coll": "寄予期望、对孩子的期望", "s": "父母对孩子的期望应当合理，也要尊重他们的兴趣。"}];
